UPDATE batch.worker_report_outbox
SET publish_status = #{publishStatus}, attempt_count = #{attemptCount}, updated_at = #{updatedAt}, claim_token = NULL
WHERE id = #{id} AND publish_status = #{statusPublishing} AND claim_token = #{claimToken}

UPDATE batch.worker_report_outbox
SET attempt_count = #{attemptCount}, next_attempt_at = #{nextAttemptAt}, updated_at = #{updatedAt}, claim_token = NULL,
    publish_status = #{publishStatus}
WHERE id = #{id} AND publish_status = #{statusPublishing} AND claim_token = #{claimToken}

UPDATE batch.worker_report_outbox
SET publish_status = #{statusNew}, updated_at = #{now}, claim_token = NULL
WHERE publish_status = #{statusPublishing} AND updated_at < #{cutoff}

UPDATE batch.worker_report_outbox SET publish_status = #{publishStatus}, updated_at = #{now}, claim_token = NULL, attempt_count =
    CASE WHEN attempt_count < #{maxAttempts} THEN #{maxAttempts} ELSE attempt_count END
WHERE id = #{id} AND publish_status = #{statusPublishing} AND claim_token = #{claimToken}
